# -*- coding: utf-8 -*-
"""
MARU HQ Phase 6.1 — Self-Extracting Engine Bundle for Git / Local Environment
"""
import base64
import zipfile
import io
from pathlib import Path

ZIP_B64 = """"""

def unpack(target_dir="."):
    print("=== MARU HQ ENGINE UNPACKER ===")
    raw = base64.b64decode(ZIP_B64)
    zip_file = Path(target_dir) / "hasil_tugas_1.zip"
    zip_file.write_bytes(raw)
    print(f"[1/2] ZIP berhasil dibuat: {zip_file.resolve()} ({len(raw)} bytes)")
    with zipfile.ZipFile(io.BytesIO(raw)) as zf:
        zf.extractall(target_dir)
        print(f"[2/2] {len(zf.namelist())} file berhasil diekstrak ke: {Path(target_dir).resolve()}")
        for item in sorted(zf.namelist()):
            print(f"  - {item}")
    print("\nSTATUS: SELESAI 100%! Semua file engine dan dokumen siap digunakan.")

if __name__ == "__main__":
    unpack()
